      const i = fs | 0, j = fd | 0, ts = fs - i, td = fd - j;
      const nd = this.nD, b = this.bed, k = i * nd + j;
      const a = b[k] + (b[k + 1] - b[k]) * td, c = b[k + nd] + (b[k + nd + 1] - b[k + nd]) * td;
