      const dy = Math.abs(this.creek.y0(Math.max(S_MIN + 1, Math.min(S_MAX - 1, s0))) - this.creek.y0(Math.max(S_MIN + 1, Math.min(S_MAX - 1, s1))));
      const lift = dy > 2 ? this.owned.has("fastLift") ? 1.5 : 4 : 0;
